 if((m=k.match(/^Zaznaczyłeś (\d+) z 5 sygnałów\. To niepełna odpowiedź\. Pamiętaj, że sygnałem dla systemu może być zarówno działanie, jak i szybkie pominięcie materiału\.$/)))return `You selected ${m[1]} of 5 signals. This is an incomplete answer. Remember that both an action and quickly skipping content can be a signal for the system.`;
