function translateElement(el,refreshOriginal=false){if(!(el instanceof Element))return;let rec=attrOriginal.get(el);if(!rec){rec={};attrOriginal.set(el,rec);}for(const a of ATTRS){if(!el.hasAttribute(a))continue;if(refreshOriginal||!(a in rec))rec[a]=el.getAttribute(a);const src=rec[a];el.setAttribute(a,language==='en'?translateString(src):src);}touchedElements.add(el);}
