function applyAll(){if(observer)observer.disconnect();busy=true;try{walk(document,false);document.documentElement.lang=language;document.body?.classList.toggle('course-lang-en',language==='en');updateSwitch();if(language==='en'){const meta=document.querySelector('meta[name="description"]');if(meta&&/Pełny kurs online/.test(meta.content))meta.content='Full online course in Media Literacy, Fake News and Critical Thinking — five modules with exercises, tests and practical verification tools.';}}finally{busy=false;connect();}}
