function insertSwitch(){if(document.querySelector('.course-language-switch'))return;const host=document.querySelector('.course-topbar-inner')||document.body;const wrap=document.createElement('div');wrap.className='course-language-switch';wrap.setAttribute('aria-label','Wybór języka / Language selection');wrap.innerHTML='<button type="button" data-course-language="pl" aria-label="Polski">PL</button><span aria-hidden="true">/</span><button type="button" data-course-language="en" aria-label="English">EN</button>';const plan=host.querySelector?.('.sidebar-open');if(plan)host.insertBefore(wrap,plan);else host.append(wrap);wrap.addEventListener('click',e=>{const b=e.target.closest('[data-course-language]');if(b)setLanguage(b.dataset.courseLanguage);});updateSwitch();}
